	/** 
	 * jumpstart the process by instantiating2 Risk
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		riskId = RiskService.getRiskInstance()
		.createRisk( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		RiskService.getRiskInstance()
				.createRisk( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.riskSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Risk : " + successValue.getRiskId());
							  if (successValue.getRiskId().equals(riskId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfRiskList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Risk test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on risk consumed")
					);
			subscriber.riskSubscribe( riskId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Risk : " + successValue.getRiskId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfRiskList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on risk for riskId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Risk. 
	 */
	protected Risk read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Risk" );

		Risk entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Risk with primary key" );
		msg.append( riskId );
		
		RiskFetchOneSummary fetchOneSummary = new RiskFetchOneSummary( riskId );

		try {
			entity = RiskService.getRiskInstance().getRisk( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Risk " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Risk.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Risk." );

		StringBuilder msg = new StringBuilder( "Failed to update a Risk : " );        
		Risk entity = read();
		UpdateRiskCommand command = generateUpdateCommand();
		command.setRiskId(entity.getRiskId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Risk." );

			// for use later on...
			riskId = entity.getRiskId();

			RiskService proxy = RiskService.getRiskInstance();  

			proxy.updateRisk( command ).get();

			LOGGER.info( "-- Successfully saved Risk - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + riskId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Risk.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Risk." );

		Risk entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Risk with id " + riskId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Risk with id " + riskId );

			throw e;
		}

		try{
			RiskService.getRiskInstance().delete( new DeleteRiskCommand( entity.getRiskId() ) ).get();
			LOGGER.info( "-- Successfully deleted Risk with id " + riskId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Risk with id " + riskId );

			throw e;
		}
	}

	/**
	 * get all Risks.
	 */
	protected List<Risk> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Risks:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Risk : " );        
		List<Risk> collection  = new ArrayList<>();

		try {
			// call the static get method on the RiskService
			collection = RiskService.getRiskInstance().getAllRisk();
			assertNotNull( collection, "An Empty collection of Risk was incorrectly returned.");
			
			// Now print out the values
			Risk entity = null;            
			Iterator<Risk> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRiskId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

